window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-dee78470e0b73123"]={"versions": [{"id": "FIG-dee78470e0b73123", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Binäres Protokoll- und PDU-Payload-Layout (Frame-Struktur / Bit- und Byte-Feld-Definition).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong></li>\n<li>Spezifiziert das Byte-Layout des Status-Frame-Headers im AUTOSAR Classic Platform Bus Mirroring Modul (<code>Mirror</code>, Service Layer).</li>\n<li>Das <code>Mirror</code>-Modul erfasst Bus-Zustände und Fehlermeldungen von Quellbussen (CAN, LIN, FlexRay) und serialisiert sie zur Überwachung auf einen Zielbus (Destination Bus, typischerweise CAN/CAN FD).</li>\n<li>Der Header dient der Protokoll-Identifikation und Abwärtskompatibilität, damit Tooling- und Analysesoftware die nachfolgenden variablen Status-Elemente (<code>Data</code>) deterministisch parsen kann.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Frame-Struktur:</strong></li>\n<li><strong>Header (Byte 0):</strong> Fester 1-Byte-Vorspann (rot akzentuiert).</li>\n<li><strong>Data (ab Byte 1):</strong> Sequentiell folgende Nutzdaten-Elemente (<code>status items</code>), die Zustandswechsel der Quellbusse kapseln.</li>\n<li><strong>Header-Feld:</strong></li>\n<li><code>ProtocolVersion</code> (1 Byte / 8 Bit): Enthält die Versionsnummer des Status-Frame-Protokolls gemäß [SWS_Mirror_00127].</li>\n<li><strong>Bit- und Byte-Ordnung:</strong></li>\n<li>Byte-Reihenfolge aufsteigend ab Index 0 (Übertragungsreihenfolge auf dem Zielbus).</li>\n<li>Bit-Ordnung innerhalb eines Bytes: MSB = Bit 7, LSB = Bit 0.</li>\n<li><strong>Kardinalitäten:</strong></li>\n<li>Exakt 1 Header-Byte pro Status-Frame ($1:1$).</li>\n<li>$N$ nachfolgende Data-Items, begrenzt durch die maximale PDU-Länge des Zielbusses (Classic CAN: max. 7 Datenbytes; CAN FD: max. 63 Datenbytes).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Puffer-Initialisierung:</strong> Bei Aktivierung eines neuen Sendepuffers schreibt das <code>Mirror</code>-Modul zwingend <code>ProtocolVersion</code> in Byte 0.</li>\n<li><strong>Pufferüberlauf & Frame-Flush ([SWS_Mirror_00125]):</strong></li>\n<li>Status-Items werden sequentiell nach dem Header angehängt.</li>\n<li>Reicht der verbleibende Platz im aktiven Puffer für ein neues Status-Item nicht aus, wird der aktuelle Puffer sofort mit der konfigurierten CAN-ID (<code>MirrorStatusCanId</code>) in die Sendewarteschlange eingereiht.</li>\n<li>Ein neuer Puffer wird allokiert, dessen Byte 0 erneut mit dem 1-Byte-Header initialisiert wird.</li>\n<li><strong>Abschluss der Erfassungsrunde ([SWS_Mirror_00126]):</strong></li>\n<li>Sobald alle Zustandsänderungen der Quellbusse abgearbeitet sind, wird der aktuell aktive Puffer in die Sendewarteschlange der PDU-Router/CanIf-Schnittstelle übergeben.</li>\n<li><strong>Trigger:</strong> Typischerweise asynchron über Bus-State-Change-Callbacks (<code>CanIf</code>, <code>LinIf</code>, <code>FrIf</code>) oder synchron innerhalb der zyklischen <code>Mirror_MainFunction()</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Puffer- und Offset-Berechnung:</strong></li>\n<li>Nutzlast-Offset für Status-Items ist strikt <code>Payload[1]</code>. Entwickler müssen sicherstellen, dass Pufferstrukturen gepackt sind (<code>#pragma pack(1)</code> bzw. <code>__attribute__((packed))</code>), um Alignment-Padding zwischen Header und Daten zu verhindern.</li>\n<li><strong>Konfigurationsparameter:</strong></li>\n<li><code>MirrorStatusCanId</code>: CAN-ID (Standard oder Extended), unter der Frames mit diesem Header gesendet werden.</li>\n<li><strong>DLC- und Übertragungslimits:</strong></li>\n<li>Für Classic CAN ($DLC = 8$) reduziert das Header-Byte die nutzbare Datenkapazität auf maximal 7 Bytes pro Frame. Das <code>Mirror</code>-Modul muss atomare Status-Items vor dem Serialisieren auf Puffergrenzen prüfen, da Items nicht über mehrere Frames fragmentiert werden dürfen.</li>\n<li><strong>Empfänger-Validierung:</strong></li>\n<li>Externe Decoder (z. B. Vector CANoe, Bus-Monitore) müssen das erste Byte zwingend gegen die erwartete <code>ProtocolVersion</code> validieren; bei Diskrepanzen ist der gesamte Frame zu verwerfen, da Format und Semantik der nachfolgenden <code>status items</code> versionsabhängig sind.</li>\n</ul>"}, {"id": "FIG-de8bf4f9560c2046", "releases": ["R19-11", "R20-11", "R21-11", "R22-11", "R23-11", "R24-11", "R25-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Binäres Protokoll- und PDU-Payload-Layout (Frame-Struktur / Bit- und Byte-Feld-Definition).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong></li>\n<li>Spezifiziert das Byte-Layout des Status-Frame-Headers im AUTOSAR Classic Platform Bus Mirroring Modul (<code>Mirror</code>, Service Layer).</li>\n<li>Das <code>Mirror</code>-Modul erfasst Bus-Zustände und Fehlermeldungen von Quellbussen (CAN, LIN, FlexRay) und serialisiert sie zur Überwachung auf einen Zielbus (Destination Bus, typischerweise CAN/CAN FD).</li>\n<li>Der Header dient der Protokoll-Identifikation und Abwärtskompatibilität, damit Tooling- und Analysesoftware die nachfolgenden variablen Status-Elemente (<code>Data</code>) deterministisch parsen kann.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Frame-Struktur:</strong></li>\n<li><strong>Header (Byte 0):</strong> Fester 1-Byte-Vorspann (rot akzentuiert).</li>\n<li><strong>Data (ab Byte 1):</strong> Sequentiell folgende Nutzdaten-Elemente (<code>status items</code>), die Zustandswechsel der Quellbusse kapseln.</li>\n<li><strong>Header-Feld:</strong></li>\n<li><code>ProtocolVersion</code> (1 Byte / 8 Bit): Enthält die Versionsnummer des Status-Frame-Protokolls gemäß [SWS_Mirror_00127].</li>\n<li><strong>Bit- und Byte-Ordnung:</strong></li>\n<li>Byte-Reihenfolge aufsteigend ab Index 0 (Übertragungsreihenfolge auf dem Zielbus).</li>\n<li>Bit-Ordnung innerhalb eines Bytes: MSB = Bit 7, LSB = Bit 0.</li>\n<li><strong>Kardinalitäten:</strong></li>\n<li>Exakt 1 Header-Byte pro Status-Frame ($1:1$).</li>\n<li>$N$ nachfolgende Data-Items, begrenzt durch die maximale PDU-Länge des Zielbusses (Classic CAN: max. 7 Datenbytes; CAN FD: max. 63 Datenbytes).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Puffer-Initialisierung:</strong> Bei Aktivierung eines neuen Sendepuffers schreibt das <code>Mirror</code>-Modul zwingend <code>ProtocolVersion</code> in Byte 0.</li>\n<li><strong>Pufferüberlauf & Frame-Flush ([SWS_Mirror_00125]):</strong></li>\n<li>Status-Items werden sequentiell nach dem Header angehängt.</li>\n<li>Reicht der verbleibende Platz im aktiven Puffer für ein neues Status-Item nicht aus, wird der aktuelle Puffer sofort mit der konfigurierten CAN-ID (<code>MirrorStatusCanId</code>) in die Sendewarteschlange eingereiht.</li>\n<li>Ein neuer Puffer wird allokiert, dessen Byte 0 erneut mit dem 1-Byte-Header initialisiert wird.</li>\n<li><strong>Abschluss der Erfassungsrunde ([SWS_Mirror_00126]):</strong></li>\n<li>Sobald alle Zustandsänderungen der Quellbusse abgearbeitet sind, wird der aktuell aktive Puffer in die Sendewarteschlange der PDU-Router/CanIf-Schnittstelle übergeben.</li>\n<li><strong>Trigger:</strong> Typischerweise asynchron über Bus-State-Change-Callbacks (<code>CanIf</code>, <code>LinIf</code>, <code>FrIf</code>) oder synchron innerhalb der zyklischen <code>Mirror_MainFunction()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Puffer- und Offset-Berechnung:</strong></li>\n<li>Nutzlast-Offset für Status-Items ist strikt <code>Payload[1]</code>. Entwickler müssen sicherstellen, dass Pufferstrukturen gepackt sind (<code>#pragma pack(1)</code> bzw. <code>__attribute__((packed))</code>), um Alignment-Padding zwischen Header und Daten zu verhindern.</li>\n<li><strong>Konfigurationsparameter:</strong></li>\n<li><code>MirrorStatusCanId</code>: CAN-ID (Standard oder Extended), unter der Frames mit diesem Header gesendet werden.</li>\n<li><strong>DLC- und Übertragungslimits:</strong></li>\n<li>Für Classic CAN ($DLC = 8$) reduziert das Header-Byte die nutzbare Datenkapazität auf maximal 7 Bytes pro Frame. Das <code>Mirror</code>-Modul muss atomare Status-Items vor dem Serialisieren auf Puffergrenzen prüfen, da Items nicht über mehrere Frames fragmentiert werden dürfen.</li>\n<li><strong>Empfänger-Validierung:</strong></li>\n<li>Externe Decoder (z. B. Vector CANoe, Bus-Monitore) müssen das erste Byte zwingend gegen die erwartete <code>ProtocolVersion</code> validieren; bei Diskrepanzen ist der gesamte Frame zu verwerfen, da Format und Semantik der nachfolgenden <code>status items</code> versionsabhängig sind.</li>\n</ul>"}], "trans": [{"from": "FIG-dee78470e0b73123", "to": "FIG-de8bf4f9560c2046", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
